BYTES = {sha: raw.encode("utf-8") for _, _, sha, raw in VECTORS}


@pytest.mark.parametrize("name,size,sha,raw", VECTORS, ids=[v[0] for v in VECTORS])
def test_literal_wire_identity(name, size, sha, raw):
    data = raw.encode("utf-8")
    assert len(data) == size
    assert hashlib.sha256(data).hexdigest() == sha
    assert canonical_bytes(decode_canonical(data)) == data
    assert typed_ref(data)["digest"] == sha


@pytest.mark.parametrize("name,size,sha,raw", VECTORS, ids=[v[0] for v in VECTORS])
def test_catalogue_byte_closure_only(name, size, sha, raw):
    closure = verify_byte_closure(typed_ref(raw.encode("utf-8")),
                                  lambda ref: BYTES[ref["digest"]])
    assert 1 <= closure.nodes <= 57
    assert 1 <= closure.depth <= 2048


@pytest.mark.parametrize("raw", [
    b'{"a": 1, "a": 2}', b'{"a":1}', b'{"a": 1}\n',
    b'\xef\xbb\xbf{}', b'{"a": NaN}', b'{"a": Infinity}',
    b'{"a": 1.0}', b'{"a": -1}', b'{"a": 9223372036854775808}',
    b'{"a": "\\ud800"}', b'{"a": "\xff"}', b'{"a": 01}',
])
def test_reject_noncanonical_or_invalid_json(raw):
    with pytest.raises(WireError):
        decode_canonical(raw)


@pytest.mark.parametrize("value", [float("nan"), 1.0, -1, MAX_INTEGER + 1,
                                   (1,), {1: "a"}, {"я": 1}, "\udfff"])
def test_reject_non_json_or_out_of_domain_values(value):
    with pytest.raises(WireError):
        canonical_bytes(value)


def test_scalars_and_unicode_are_preserved():
    value = {"z": [None, True, False, 0, MAX_INTEGER, "Київ", "ё", "е\u0308"]}
    assert decode_canonical(canonical_bytes(value)) == value
    assert canonical_bytes("ё") != canonical_bytes("е\u0308")
    assert canonical_bytes({"b": 2, "a": 1}) == b'{"a": 1, "b": 2}'


@pytest.mark.parametrize("change", [
    {"version": 1}, {"version": True}, {"scope": "PURE"},
    {"kind": "PURE.ProofAck"}, {"digest": "A" * 64}, {"digest": "0" * 63},
    {"extra": False}, {"kind": []},
])
def test_ref_rejects_aliases_and_open_shapes(change):
    ref = typed_ref(VECTORS[0][3].encode("utf-8"))
    ref.update(change)
    with pytest.raises(WireError):
        validate_ref(ref)


def test_reference_fields_are_required():
    ref = typed_ref(VECTORS[0][3].encode("utf-8"))
    for key in list(ref):
        bad = dict(ref)
        del bad[key]
        with pytest.raises(WireError):
            validate_ref(bad)


def test_missing_and_substituted_reference_bytes():
    ref = typed_ref(VECTORS[1][3].encode("utf-8"))
    with pytest.raises(WireError, match="Unresolved"):
        verify_byte_closure(ref, lambda _: {}["missing"])
    with pytest.raises(WireError, match="identity"):
        verify_byte_closure(ref, lambda _: VECTORS[0][3].encode("utf-8"))


def test_kind_mismatch_is_not_a_digest_alias():
    ref = typed_ref(VECTORS[0][3].encode("utf-8"))
    ref["kind"] = "DQ.LAB.RootAnchor"
    with pytest.raises(WireError, match="identity"):
        verify_byte_closure(ref, lambda _: VECTORS[0][3].encode("utf-8"))


def test_cyclic_input_and_resource_guards():
    value = []
    value.append(value)
    with pytest.raises(WireError, match="Cyclic"):
        canonical_bytes(value)
    with pytest.raises(WireError, match="byte limit"):
        canonical_bytes("x" * (4 * 1024 * 1024))
    nested = None
    for _ in range(66):
        nested = [nested]
    with pytest.raises(WireError, match="resource"):
        canonical_bytes(nested)


def test_payload_bytes_are_not_opaque():
    obj = json.loads(next(v[3] for v in VECTORS if v[0] == "D_JOB"))
    payload = decode_canonical(bytes.fromhex(obj["payload_hex"]))
    payload["request_ref"]["digest"] = "0" * 64
    raw = canonical_bytes(payload)
    obj.update(payload_hex=raw.hex(), byte_length=len(raw),
               raw_sha256=hashlib.sha256(raw).hexdigest())
    data = canonical_bytes(obj)
    nodes = dict(BYTES)
    nodes[hashlib.sha256(data).hexdigest()] = data
    with pytest.raises(WireError, match="Unresolved"):
        verify_byte_closure(typed_ref(data), lambda ref: nodes[ref["digest"]])


def test_payload_raw_digest_and_wrapper_digest_differ():
    obj = json.loads(next(v[3] for v in VECTORS if v[0] == "D_JOB"))
    assert typed_ref(canonical_bytes(obj))["digest"] != obj["raw_sha256"]
    obj["raw_sha256"] = "0" * 64
    data = canonical_bytes(obj)
    with pytest.raises(WireError, match="payload hash"):
        verify_byte_closure(typed_ref(data), lambda _: data)


def test_wire_hash_explicitly_does_not_validate_proof_semantics():
    # An arbitrary header-bearing object is hashable; this API intentionally
    # cannot be used as a schema validator or a native authorization signal.
    data = canonical_bytes({"kind": "DQ.LAB.ProofAck", "version": 2,
                            "scope": SCOPE, "not_a_proof": True})
    assert typed_ref(data)["kind"] == "DQ.LAB.ProofAck"


